import unittest
from candidate import triangle_area

class TestTriangleArea(unittest.TestCase):
    def test_triangle_area_valid_triangle(self):
        self.assertAlmostEqual(triangle_area(3, 4, 5), 6.00)

    def test_triangle_area_invalid_triangle(self):
        self.assertEqual(triangle_area(1, 2, 10), -1)

    def test_triangle_area_all_sides_equal(self):
        self.assertAlmostEqual(triangle_area(5, 5, 5), 10.83)

    def test_triangle_area_two_sides_equal(self):
        self.assertAlmostEqual(triangle_area(3, 3, 4), 2.60)

    def test_triangle_area_one_side_zero(self):
        self.assertEqual(triangle_area(0, 3, 4), -1)

    def test_triangle_area_all_sides_zero(self):
        self.assertEqual(triangle_area(0, 0, 0), -1)

    def test_triangle_area_negative_sides(self):
        with self.assertRaises(TypeError):
            triangle_area(-3, 4, 5)

    def test_triangle_area_non_numeric_sides(self):
        with self.assertRaises(TypeError):
            triangle_area('a', 4, 5)

    def test_triangle_area_none_sides(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 4, 5)

if __name__ == '__main__':
    unittest.main()
